#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int HPY, ATKY, DEFY;
    int HPM, ATKM, DEFM;
    int h, a, d;
    if (!(cin >> HPY >> ATKY >> DEFY)) return 0;
    cin >> HPM >> ATKM >> DEFM;
    cin >> h >> a >> d;

    const int INF = 1e9;
    int ans = INF;

    // Upper bounds for search
    int maxAtk = 200; // enough since inputs <=100 and we only need reasonable range
    int maxDef = 200;

    for (int atkY = ATKY; atkY <= maxAtk; ++atkY) {
        for (int defY = DEFY; defY <= maxDef; ++defY) {
            int dmgToM = max(0, atkY - DEFM);
            if (dmgToM == 0) continue; // can't kill monster

            int turnsToKillM = (HPM + dmgToM - 1) / dmgToM;

            int dmgToY = max(0, ATKM - defY);
            int neededHP;
            if (dmgToY == 0) {
                neededHP = 1; // any positive HP is enough
            } else {
                // Yang must survive turnsToKillM - 1 hits
                neededHP = (turnsToKillM - 1) * dmgToY + 1;
            }

            int extraHP = max(0, neededHP - HPY);
            int cost = (atkY - ATKY) * a + (defY - DEFY) * d + extraHP * h;
            ans = min(ans, cost);
        }
    }

    cout << ans << '\n';
